#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

PX4_DIR="${PX4_DIR:-$HOME/PX4-Autopilot}"
REPO_DIR="${REPO_DIR:-$HOME/uav-yolo-offboard-tracking}"
REPO_URL="https://github.com/wuuu854-boop/uav-yolo-offboard-tracking.git"
ROS_DISTRO_NAME="humble"

have() { command -v "$1" >/dev/null 2>&1; }

# ROS setup files reference unset variables, which `set -u` turns into a crash.
source_ros() {
  set +u
  # shellcheck disable=SC1091
  source "/opt/ros/${ROS_DISTRO_NAME}/setup.bash"
  if [[ -f "$REPO_DIR/ros_ws/install/setup.bash" ]]; then
    # shellcheck disable=SC1091
    source "$REPO_DIR/ros_ws/install/setup.bash"
  fi
  set -u
}

require_ok() {
  if ! confirm "$1"; then
    printf '  %s✗ stopped.%s Fix it and re-run; completed stages are skipped automatically.\n' "$RED" "$RESET"
    exit 1
  fi
}

banner "PX4 SITL setup (Ubuntu 22.04 / WSL2)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the machine"
say "This wizard assumes Ubuntu 22.04 (jammy), which is what WSL2 gives you."
say "It installs ROS 2 Humble, Gazebo Harmonic, PX4 v1.15 and this repo."
echo

if [[ -r /etc/os-release ]]; then
  # shellcheck disable=SC1091
  . /etc/os-release
  say "detected: ${PRETTY_NAME:-unknown}"
  if [[ "${VERSION_ID:-}" != "22.04" ]]; then
    warn "expected Ubuntu 22.04; ROS 2 Humble has no packages for this release."
    require_ok "Continue anyway (only sensible if you know why)?"
  else
    step "Ubuntu 22.04 — good."
  fi
fi

free_gb=$(df -Pk "$HOME" | awk 'NR==2 {printf "%d", $4/1024/1024}')
say "free space in \$HOME: ${free_gb} GB (need ~20 GB: ROS 2 + Gazebo + PX4 build)"
if (( free_gb < 15 )); then
  warn "not enough space; the PX4 build alone needs several GB."
  require_ok "Continue anyway?"
fi

if grep -qi microsoft /proc/version 2>/dev/null; then
  step "running inside WSL — GUI windows open through WSLg."
  note "if Gazebo opens a black window later, run: export LIBGL_ALWAYS_SOFTWARE=1"
else
  step "running on native Linux."
fi
pause "Press Enter to continue."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Base build tools"
say "git, cmake, a compiler, pip and the colcon build tool."
if have git && have cmake && have gcc && have python3 && have pip3; then
  step "already installed — skipping."
else
  if confirm "Install them now (needs sudo)?"; then
    sudo apt-get update
    sudo apt-get install -y git cmake build-essential curl lsb-release gnupg \
      python3-pip python3-venv python3-dev
  fi
fi
python3 --version
pause "Press Enter to continue."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "ROS 2 Humble"
if [[ -d "/opt/ros/${ROS_DISTRO_NAME}" ]]; then
  step "already installed at /opt/ros/${ROS_DISTRO_NAME} — skipping."
else
  say "Adding the official ROS 2 apt repository, then installing the base plus"
  say "cv_bridge (image conversion) and ros_gz_bridge (Gazebo <-> ROS)."
  if confirm "Install ROS 2 Humble (needs sudo, ~1 GB)?"; then
    sudo apt-get install -y software-properties-common curl
    sudo add-apt-repository -y universe
    sudo curl -sSL https://raw.githubusercontent.com/ros/rosdistro/master/ros.key \
      -o /usr/share/keyrings/ros-archive-keyring.gpg
    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/ros-archive-keyring.gpg] http://packages.ros.org/ros2/ubuntu $(lsb_release -cs) main" \
      | sudo tee /etc/apt/sources.list.d/ros2.list > /dev/null
    sudo apt-get update
    sudo apt-get install -y \
      "ros-${ROS_DISTRO_NAME}-ros-base" \
      "ros-${ROS_DISTRO_NAME}-cv-bridge" \
      "ros-${ROS_DISTRO_NAME}-ros-gz-bridge" \
      "ros-${ROS_DISTRO_NAME}-rosidl-default-generators" \
      "ros-${ROS_DISTRO_NAME}-rosidl-default-runtime" \
      "ros-${ROS_DISTRO_NAME}-rmw-cyclonedds-cpp" \
      python3-colcon-common-extensions
  fi
fi

if [[ -f "/opt/ros/${ROS_DISTRO_NAME}/setup.bash" ]]; then
  source_ros
  ros2 --help >/dev/null 2>&1 && step "ros2 CLI responds."
  say "Add it to your shell so every new terminal has it:"
  step "echo 'source /opt/ros/${ROS_DISTRO_NAME}/setup.bash' >> ~/.bashrc"
else
  warn "ROS 2 is not installed; stop here."
  exit 1
fi
pause "Press Enter to continue."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Gazebo Harmonic (gz-sim 8)"
if have gz && gz sim --versions 2>/dev/null | grep -q '8\.'; then
  step "already installed — $(gz sim --versions 2>/dev/null | head -n1)"
else
  say "PX4 v1.15 talks to Gazebo through gz-transport, which needs Harmonic (8.x)."
  if confirm "Install gz-harmonic from the OSRF repository (needs sudo)?"; then
    sudo curl -sSL https://packages.osrfoundation.org/gazebo.gpg \
      -o /usr/share/keyrings/pkgs-osrf-archive-keyring.gpg
    # shellcheck disable=SC1091
    echo "deb [arch=$(dpkg --print-architecture) signed-by=/usr/share/keyrings/pkgs-osrf-archive-keyring.gpg] http://packages.osrfoundation.org/gazebo/ubuntu-stable $(lsb_release -cs) main" \
      | sudo tee /etc/apt/sources.list.d/gazebo-stable.list > /dev/null
    sudo apt-get update
    sudo apt-get install -y gz-harmonic
  fi
fi

if have gz; then
  gz sim --versions 2>/dev/null | head -n 1
else
  warn "gz not found on PATH after install; check the OSRF repository above."
  require_ok "Continue anyway?"
fi
pause "Press Enter to continue."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "PX4 v1.15 source"
if [[ -d "$PX4_DIR/.git" ]]; then
  step "already cloned at $PX4_DIR — skipping."
else
  say "Cloning the exact release this project pins (v1.15.0) with submodules."
  note "This is ~1 GB and takes a few minutes."
  if confirm "Clone PX4 into $PX4_DIR?"; then
    git clone --recursive -b v1.15.0 https://github.com/PX4/PX4-Autopilot.git "$PX4_DIR"
  fi
fi

if [[ -d "$PX4_DIR/.git" ]]; then
  say "Installing PX4's own Ubuntu dependencies (no NuttX toolchain: we fly SITL)."
  if confirm "Run Tools/setup/ubuntu.sh --no-nuttx (needs sudo)?"; then
    ( cd "$PX4_DIR" && bash Tools/setup/ubuntu.sh --no-nuttx )
  fi
else
  warn "PX4 is missing; cannot continue."
  exit 1
fi
pause "Press Enter to continue."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Build the firmware"
if [[ -x "$PX4_DIR/build/px4_sitl_default/bin/px4" ]]; then
  step "already built — skipping."
else
  say "First build takes 10–20 minutes on a laptop. It is one long compile;"
  say "if it fails, the last 20 lines name the missing package."
  if confirm "Build now (make px4_sitl_default)?"; then
    ( cd "$PX4_DIR" && make px4_sitl_default -j"$(nproc)" )
  fi
fi

if [[ -x "$PX4_DIR/build/px4_sitl_default/bin/px4" ]]; then
  step "build/px4_sitl_default/bin/px4 exists."
  note "the first 'make sim' also compiles the Gazebo plugin; that is expected."
else
  warn "no PX4 binary yet — run 'make px4_sitl_default' in $PX4_DIR and re-run."
  require_ok "Continue anyway?"
fi
pause "Press Enter to continue."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "This repo and its ROS interface package"
if [[ -d "$REPO_DIR/.git" ]]; then
  step "already cloned at $REPO_DIR — skipping."
else
  if confirm "Clone this repo into $REPO_DIR? (keep it in the Linux filesystem, not /mnt/c — it is much faster)"; then
    git clone "$REPO_URL" "$REPO_DIR"
  fi
fi

if [[ ! -d "$REPO_DIR/.git" ]]; then
  warn "repo missing; cannot continue."
  exit 1
fi

say "px4_msgs must be built against the same PX4 version, and uav_interfaces"
say "carries the TargetArray message both nodes use."
if [[ -f "$REPO_DIR/ros_ws/install/setup.bash" ]]; then
  step "ROS workspace already built — skipping."
else
  if confirm "Create ros_ws, link px4_msgs + uav_interfaces and run colcon build?"; then
    mkdir -p "$REPO_DIR/ros_ws/src"
    if [[ -d "$REPO_DIR/ros_ws/src/px4_msgs/.git" ]]; then
      step "px4_msgs already present."
    else
      git clone -b release/1.15 https://github.com/PX4/px4_msgs.git "$REPO_DIR/ros_ws/src/px4_msgs"
    fi
    ln -sfn "$REPO_DIR/src/uav_interfaces" "$REPO_DIR/ros_ws/src/uav_interfaces"
    source_ros
    ( cd "$REPO_DIR/ros_ws" && colcon build --symlink-install )
  fi
fi

if [[ -f "$REPO_DIR/ros_ws/install/setup.bash" ]]; then
  step "ros_ws/install/setup.bash exists."
  note "source it in every terminal: source $REPO_DIR/ros_ws/install/setup.bash"
else
  warn "workspace not built; the nodes will not import uav_interfaces."
  require_ok "Continue anyway?"
fi

say "Installing the Python package itself (editable, numpy pinned <2 for cv_bridge)."
if confirm "Run 'pip install -e .' in $REPO_DIR?"; then
  ( cd "$REPO_DIR" && python3 -m pip install --user -e . )
fi
pause "Press Enter to continue."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Micro XRCE-DDS Agent"
if have MicroXRCEAgent; then
  step "already installed — $(command -v MicroXRCEAgent)"
else
  say "PX4 talks to ROS 2 over uXRCE-DDS; this is the bridge process."
  say "The version pinned below matches the PX4 v1.15 documentation."
  open_url "https://docs.px4.io/v1.15/en/ros/ros2_comm.html"
  if confirm "Clone and build Micro-XRCE-DDS-Agent v2.4.3 (needs sudo for install)?"; then
    if [[ ! -d "$HOME/Micro-XRCE-DDS-Agent/.git" ]]; then
      git clone -b v2.4.3 https://github.com/eProsima/Micro-XRCE-DDS-Agent.git "$HOME/Micro-XRCE-DDS-Agent"
    fi
    ( cd "$HOME/Micro-XRCE-DDS-Agent" && mkdir -p build && cd build \
      && cmake .. && make -j"$(nproc)" && sudo make install && sudo ldconfig )
  fi
fi

if have MicroXRCEAgent; then
  step "MicroXRCEAgent on PATH."
else
  warn "not on PATH; check the build output, or the docs page above."
fi
pause "Press Enter to continue."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Install the world and check everything"
if [[ -d "$PX4_DIR/.git" && -d "$REPO_DIR/.git" ]]; then
  if confirm "Copy the target world into PX4 and run the environment checks?"; then
    ( cd "$REPO_DIR" && PX4_DIR="$PX4_DIR" make install-world )
    # doctor reports problems and exits non-zero; that is information, not a
    # reason to abort the wizard.
    ( cd "$REPO_DIR" && PX4_DIR="$PX4_DIR" make doctor ) || true
  fi
fi

say "Then, in three terminals:"
step "A:  cd $REPO_DIR && PX4_DIR=$PX4_DIR make sim"
step "B:  cd $REPO_DIR && source ros_ws/install/setup.bash && make preflight"
step "C:  cd $REPO_DIR && source ros_ws/install/setup.bash && MicroXRCEAgent udp4 -p 8888   # only if PX4 does not start it"
note "make preflight starts nothing; it checks configs, imports and directories."
note "make e2e then flies one trial and writes results/."
pause "Press Enter to finish."

finish
